# =============================== C03 ===============================
s6 = spec.ANS["C03-Q6"]
level(3, "🧮", "סדרות דרגות ואלגוריתם Havel-Hakimi", "להחליט אם סדרת מספרים היא סדרת הדרגות של גרף, ולהסביר למה.", r"""
<p>סדרה של מספרים טבעיים היא <b>גרפית</b> אם קיים גרף פשוט שהדרגות של צמתיו הן בדיוק הסדרה. שני תנאים הכרחיים: הסכום <b>זוגי</b>, והמספר הגדול ביותר <b>קטן מ-$n$</b> (מספר איברי הסדרה). אבל הם לא מספיקים: הסדרה $3,3,1,1$ עוברת את שניהם ואינה גרפית.</p>
<div class="lesson-rule">🔑 <b>אלגוריתם Havel-Hakimi:</b> (1) מסדרים את הסדרה בסדר יורד. (2) מוחקים את האיבר הראשון $d$ ומפחיתים 1 מ-$d$ האיברים הבאים; אם אין מספיק איברים או שמתקבל מספר שלילי, הסדרה לא גרפית. (3) חוזרים על השלבים עד שכל האיברים 0 (הסדרה גרפית) או עד כישלון.</div>
<p>הרעיון: צומת בדרגה $d$ אפשר לחבר לצמתים בעלי הדרגות הגדולות ביותר, ולכן אחרי מחיקתו נשארת בעיה קטנה יותר.</p>
<div class="lesson-ex"><b>דוגמה:</b> האם $3,2,2,2,1$ גרפית? מוחקים 3 ומפחיתים משלושת הבאים: $1,1,1,1$. מוחקים 1: $0,1,1$, כלומר $1,1,0$. מוחקים 1: $0,0$. הכול אפס, ולכן הסדרה גרפית.</div>
<div class="lesson-trap">⚠️ צומת בדרגה $n-1$ מחובר לכל הצמתים האחרים, ולכן לא יכול להיות בגרף אותו צומת בדרגה 0. לכן אין גרף על $n\ge2$ צמתים שבו כל הדרגות שונות זו מזו.</div>
""", [
    mcq("C03-Q1", r"איזו מהסדרות הבאות (כולן עם סכום זוגי) היא <b>לא</b> סדרת דרגות של גרף?",
        ["$3,3,2,2,2$", "$4,2,2,1,1$", ANS["C03-Q1"], "$3,3,3,3$"],
        r"ב-$4,4,3,1,1,1$ מוחקים 4 ומפחיתים מארבעת הבאים: $3,2,0,0,1$, כלומר $3,2,1,0,0$. מוחקים 3 ומפחיתים משלושת הבאים: $1,0,-1,0$, מספר שלילי, ולכן הסדרה לא גרפית. השאר גרפיות: $3,3,3,3$ הוא $K_4$, ו-$4,2,2,1,1$ מתקבלת מ-$1,1,0,0$ אחרי חיבור צומת לארבעת הצמתים.", r"סכום זוגי לא מספיק: מריצים Havel-Hakimi."),
    mcq("C03-Q2", r"מריצים צעד אחד של Havel-Hakimi על הסדרה $4,3,3,2,2,1,1$. מהי הסדרה שמתקבלת (בסדר יורד)?",
        [fmt(ANS["C03-Q2"]), "$3,2,2,1,1,1$", "$2,2,1,1,1,0$", "$3,3,2,2,1,1$"],
        r"מוחקים 4 ומפחיתים 1 מארבעת הבאים $3,3,2,2$: מתקבל $2,2,1,1$, ושני האיברים האחרונים $1,1$ לא משתנים. התוצאה $2,2,1,1,1,1$. בתשובות האחרות הופחת מהצמתים הלא נכונים או במספר לא נכון של צמתים.", r"מוחקים $d$ ומפחיתים 1 מ-$d$ הבאים."),
    mcq("C03-Q3", r"האם קיים גרף פשוט על 7 צמתים שבו כל הדרגות שונות זו מזו?",
        ["כן, למשל מסלול", ANS["C03-Q3"], "כן, אבל רק אם הסכום זוגי", "לא, כי 7 מספר אי-זוגי"],
        r"בגרף על 7 צמתים הדרגות בין 0 ל-6, ולכן 7 דרגות שונות הן בדיוק $0,1,\dots,6$. אבל צומת בדרגה 6 מחובר לכולם, כולל לצומת בדרגה 0. סתירה. במסלול יש דרגות חוזרות.", r"דרגה $n-1$ ודרגה 0 לא מופיעות יחד."),
    num("C03-Q4", r"סדרת הדרגות $5,4,3,3,2,2,2,1$ גרפית. כמה צלעות יש בגרף?",
        r"הסכום $5+4+3+3+2+2+2+1=22$, ולכן $|E|=11$.", r"$|E|=\frac12\sum d_i$."),
    mcq("C03-Q5", r"האם $7,6,5,5,3,2,2,2$ היא סדרת דרגות של גרף?",
        ["כן, כי הסכום זוגי", ANS["C03-Q5"], "לא, כי הסכום אי-זוגי", "כן, כי הדרגה המקסימלית קטנה מ-8"],
        r"הסכום $32$ זוגי והמקסימום $7<8$, אבל מוחקים 7: $5,4,4,2,1,1,1$. מוחקים 5: $3,3,1,0,0,1$, כלומר $3,3,1,1,0,0$. מוחקים 3: $2,0,0,0,0$. מוחקים 2: צריך להפחית מהשניים הבאים, שהם 0 ו-0, ומתקבל מספר שלילי. אין גרף כזה.", r"שני התנאים ההכרחיים לא מספיקים."),
    order("C03-Q6", r"סדרו את שלבי Havel-Hakimi על הסדרה $3,3,2,2,1,1$.",
          [r"מוחקים 3 ומפחיתים 1 מהשלושה הבאים: " + fmt(s6[0]),
           r"מוחקים 2 ומפחיתים 1 מהשניים הבאים: " + fmt(s6[1]),
           r"מוחקים 1 ומפחיתים 1 מהבא: " + fmt(s6[2]),
           r"כל האיברים אפס, ולכן הסדרה גרפית"],
          r"כל שלב מתחיל בסדרה שנוצרה בקודמו, ולכן הסדר קבוע.", r"ממשיכים עד אפסים (גרפית) או עד איבר שלילי."),
])

# =============================== C04 ===============================
level(4, "🔀", "גרפים דו-צדדיים", "לזהות גרף דו-צדדי, לספור צלעות לפי הצדדים, ולהסביר למה המשלים שלו כמעט אף פעם לא דו-צדדי.", r"""
<p>גרף $G=(A,B,E)$ הוא <b>דו-צדדי</b> אם אפשר לחלק את הצמתים לשתי קבוצות לא ריקות וזרות $A,B$, כך שכל צלע מחברת צומת מ-$A$ לצומת מ-$B$. אין צלעות בתוך צד.</p>
<div class="lesson-rule">🔑 גרף דו-צדדי אם ורק אם אין בו מעגל <b>באורך אי-זוגי</b>. בפרט $C_n$ עם $n$ זוגי דו-צדדי, $C_n$ עם $n$ אי-זוגי לא, וגם $K_n$ עבור $n\ge3$ לא (יש בו משולש).</div>
<ul>
<li><b>דו-צדדי שלם</b> $K_{m,n}$: כל צומת של $A$ ($|A|=m$) מחובר לכל צומת של $B$ ($|B|=n$). יש בו $mn$ צלעות.</li>
<li>בכל גרף דו-צדדי כל צלע נספרת פעם אחת בצד $A$ ופעם אחת בצד $B$: $\sum_{a\in A}\deg(a)=\sum_{b\in B}\deg(b)=|E|$.</li>
<li>אם $|A|=a$ ו-$|B|=n-a$, יש לכל היותר $a(n-a)$ צלעות.</li>
</ul>
<div class="lesson-ex"><b>דוגמה:</b> בגרף דו-צדדי עם $|A|=3$ שבו כל צומת של $A$ בדרגה 4 יש $12$ צלעות. אם $|B|=6$ וכל דרגות $B$ שוות, כל צומת של $B$ בדרגה 2.</div>
<div class="lesson-trap">⚠️ משלים של גרף דו-צדדי על 5 צמתים או יותר <b>אינו</b> דו-צדדי: לפחות אחד הצדדים מכיל 3 צמתים, ובמקור אין ביניהם צלעות, ולכן במשלים הם יוצרים משולש. משולש הוא מעגל אי-זוגי.</div>
""", [
    num("C04-Q1", r"כמה צלעות יש ב-$K_{5,7}$ ?", r"כל אחד מ-5 צמתי $A$ מחובר לכל 7 צמתי $B$: $5\cdot7=35$.", r"$|E(K_{m,n})|=mn$."),
    mcq("C04-Q2", r"איזה מהגרפים הבאים דו-צדדי?",
        ["$C_7$", ANS["C04-Q2"], "$K_4$", "$K_5$"],
        r"$C_8$ הוא מעגל באורך זוגי, ולכן אפשר לצבוע את צמתיו לסירוגין בשני צדדים. ב-$C_7$ יש מעגל באורך 7 (אי-זוגי), וב-$K_4$ ו-$K_5$ יש משולשים.", r"אין מעגל אי-זוגי: דו-צדדי."),
    num("C04-Q3", r"בגרף דו-צדדי $|A|=4$ וכל צומת של $A$ בדרגה 3. ב-$B$ יש 6 צמתים, וכולם באותה דרגה. מהי הדרגה של צומת ב-$B$ ?",
        r"מספר הצלעות $4\cdot3=12$, וגם $6\cdot d=12$. לכן $d=2$.", r"$\sum_A\deg=\sum_B\deg=|E|$."),
    mcq("C04-Q4", r"האם המשלים של $K_{2,5}$ הוא דו-צדדי?",
        ["כן, כי $K_{2,5}$ דו-צדדי", ANS["C04-Q4"], "לא, כי יש בו 7 צמתים", "כן, כי הוא קשיר"],
        r"המשלים הוא $K_2\cup K_5$. הצד בן 5 הצמתים הופך לקליקה $K_5$, ובה משולש. תכונה של גרף לא עוברת למשלים שלו. 7 צמתים לבדם לא מונעים דו-צדדיות, והמשלים אף אינו קשיר.", r"צד עם 3 צמתים נהפך למשולש במשלים."),
    num("C04-Q5", r"מהו מספר הצלעות המרבי בגרף דו-צדדי על 9 צמתים?",
        r"אם $|A|=a$ אז $|B|=9-a$ ומספר הצלעות לכל היותר $a(9-a)$. הערך הגדול ביותר ב-$a=4$ או $a=5$: $4\cdot5=20$.", r"מקסימום $a(n-a)$, בצדדים שווים ככל האפשר."),
    num("C04-Q6", r"בגרף דו-צדדי דרגות הצמתים ב-$A$ הן $4,3,3,2$. ב-$B$ יש חמישה צמתים בדרגות $3,3,2,2,x$. מהו $x$ ?",
        r"בצד $A$ יש $4+3+3+2=12$ צלעות. ב-$B$: $3+3+2+2+x=12$, לכן $x=2$.", r"סכום הדרגות בכל צד שווה למספר הצלעות."),
])

# =============================== C05 ===============================
level(5, "🌳", "עצים ויערות", "לזהות עץ, ולחשב מספר צלעות, רכיבים ועלים לפי מספר הצמתים.", r"""
<p><b>עץ</b> הוא גרף קשיר בלי מעגלים. <b>יער</b> הוא גרף בלי מעגלים (איחוד זר של עצים). <b>עלה</b> הוא צומת בדרגה 1.</p>
<div class="lesson-rule">🔑 בגרף על $n$ צמתים כל אחד מהתנאים הבאים שקול ל"עץ": (1) קשיר וגם $|E|=n-1$; (2) בלי מעגלים וגם $|E|=n-1$; (3) לכל שני צמתים יש מסלול <b>יחיד</b> ביניהם.</div>
<ul>
<li>ביער עם $n$ צמתים ו-$k$ רכיבי קשירות יש $|E|=n-k$ צלעות, כלומר $k=n-|E|$.</li>
<li>לכל עץ עם $n\ge2$ צמתים יש לפחות <b>שני עלים</b>: שני קצות המסלול הארוך ביותר.</li>
<li>הסרת עלה מעץ משאירה עץ.</li>
</ul>
<div class="lesson-ex"><b>דוגמה:</b> יער עם 20 צמתים ו-3 רכיבים הוא בעל $20-3=17$ צלעות.</div>
<div class="lesson-trap">⚠️ התנאי $|E|=n-1$ לבדו לא מספיק: צריך גם קשירות או גם היעדר מעגלים. משולש וצומת מבודד: 4 צמתים, 3 צלעות, אבל זה לא עץ.</div>
""", [
    num("C05-Q1", r"כמה צלעות יש בעץ עם 15 צמתים?", r"$|E|=n-1=14$.", r"עץ על $n$ צמתים: $n-1$ צלעות."),
    num("C05-Q2", r"ביער יש 20 צמתים ו-3 רכיבי קשירות. כמה צלעות יש בו?", r"$|E|=n-k=20-3=17$.", r"יער: $|E|=n-k$."),
    num("C05-Q3", r"ביער יש 30 צמתים ו-24 צלעות. כמה רכיבי קשירות יש בו?", r"$k=n-|E|=30-24=6$.", r"$k=n-|E|$."),
    mcq("C05-Q4", r"בגרף 7 צמתים ו-6 צלעות. איזה תנאי נוסף <b>מבטיח</b> שהוא עץ?",
        ["אין בו צומת מבודד", ANS["C05-Q4"], "יש בו צומת בדרגה 3", "הוא דו-צדדי"],
        r"קשיר ו-$|E|=n-1$ הם עץ לפי משפט האפיון. שאר התנאים לא מספיקים: משולש ועוד כוכב $K_{1,3}$ הם גרף עם 7 צמתים ו-6 צלעות, בלי צומת מבודד ועם דרגה 3, ואינו עץ. ו-$C_4$ ועוד מסלול על 3 צמתים הוא דו-צדדי ואינו עץ.", r"$n-1$ צלעות ועוד קשיר (או בלי מעגלים) הם עץ."),
    mcq("C05-Q5", r"מסירים עלה מעץ עם לפחות 3 צמתים. מה מתקבל?",
        ["יער עם שני רכיבים", ANS["C05-Q5"], "גרף עם מעגל", "גרף לא קשיר"],
        r"העלה נוגע בצלע אחת בלבד, ולכן מסלולים בין שאר הצמתים לא עברו דרכו. הגרף נשאר קשיר, ואין בו מעגלים: עץ עם צומת אחד פחות.", r"הסרת עלה משאירה עץ."),
    mcq("C05-Q6", r"מהו מספר העלים המזערי של עץ עם $n\ge2$ צמתים?",
        ["1", "2", "$n-1$", "אין חסם"],
        r"בעץ יש לפחות שני עלים: המסלול הארוך ביותר מתחיל ומסתיים בצמתים שדרגתם 1. המסלול $P_n$ מראה שיש עץ עם בדיוק שני עלים.", r"לעץ עם $n\ge2$ לפחות שני עלים."),
])
